mapper.select:
select sum(amount) from orders


       and order_time between #{beginTime} and #{endTime}


        and status = #{status}

select sum(t1.number) as count, t1.name from order_detail t1, orders t2 where t1.order_id = t2.id and t2.status = 5
and t2.order_time between #{beginTime} and #{endTime}
group by t1.name order by count desc limit 0,10;
